class Solution {
public:
    std::string oddString(std::vector<std::string>& words) {
        std::map<std::vector<int>, std::vector<std::string>> diffs;
        for (const auto& w : words) {
            std::vector<int> d;
            for (size_t i = 0; i + 1 < w.size(); ++i) {
                d.push_back(w[i + 1] - w[i]);
            }
            diffs[d].push_back(w);
        }
        for (const auto& pair : diffs) {
            if (pair.second.size() == 1) return pair.second[0];
        }
        return "";
    }
};

class Solution {
    public String oddString(String[] words) {
        java.util.Map<String, java.util.List<String>> diffs = new java.util.HashMap<>();
        for (String w : words) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i + 1 < w.length(); i++) {
                sb.append(w.charAt(i + 1) - w.charAt(i)).append(',');
            }
            String key = sb.toString();
            diffs.computeIfAbsent(key, k -> new java.util.ArrayList<>()).add(w);
        }
        for (java.util.List<String> list : diffs.values()) {
            if (list.size() == 1) return list.get(0);
        }
        return "";
    }
}

var oddString = function(words) {
    const diffs = new Map();
    for (const w of words) {
        const d = [];
        for (let i = 0; i + 1 < w.length; i++) {
            d.push(w.charCodeAt(i + 1) - w.charCodeAt(i));
        }
        const key = d.join(',');
        if (!diffs.has(key)) diffs.set(key, []);
        diffs.get(key).push(w);
    }
    for (const list of diffs.values()) {
        if (list.length === 1) return list[0];
    }
    return '';
};
